sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var employees = [],
        userMails = [];
    var empArr = event.payload.value;
    for (var emp in empArr){
        var employee = empArr[emp];
        employees.push({
            "id": employee.id,
            "label": employee.label,
			"sublabel": employee.sublabel,
            "avatarProps": {
            "userName": "",
            "imageSrc": "?t=small",
            "presence": "available"
        }
        });
        userMails.push(employee.sublabel);
    }

    api.setState("employeeEmailsList", userMails.join(","));
    api.setState("employeeEmails", employees);
}
